corrected_code:
const documentCollaborationResolvers = {
  Subscription: {
    documentDeltaApplied: {
      subscribe: async (parent, { docId }, context) => {
        if (!context.user) throw new Error('Unauthorized');
        const doc = await Document.findOne({
          where: { id: docId, organizationId: context.user.organizationId }
        });
        if (!doc) throw new Error('Access to document stream denied');
        return pubsub.asyncIterator([`DOC_${docId}_DELTAS`]);
      },
      resolve: (payload) => payload.delta
    }
  }
};
